#include <stack>
#include <iostream>

void safe_pop(std::stack<int>& s) {
    if (!s.empty()) { 
        int value = s.top();
        s.pop();
        // Process value...
    } else {
        std::cerr << "Error: Stack is empty." << std::endl;
    }
}

int main() {
    std::stack<int> s;
    // s.pop(); // DANGER: Undefined Behavior if uncommented!
    safe_pop(s);
}
